// Makes the widget providers generated by react-native-android-widget extend
// FastWidgetProvider (modules/hue-http), which sends "FAST_*" widget taps to the
// bridge from native code before JS starts. Runs after every other mod, so it sees
// the files the widget plugin wrote.
const { withFinalizedMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

module.exports = function withFastWidgets(config, { widgets }) {
  return withFinalizedMod(config, [
    'android',
    async (cfg) => {
      const pkg = cfg.android.package;
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/java', ...pkg.split('.'), 'widget');
      for (const name of widgets) {
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(
          path.join(dir, `${name}.java`),
          `package ${pkg}.widget;\n\nimport io.lechaterrant.huehttp.FastWidgetProvider;\n\npublic class ${name} extends FastWidgetProvider {\n}\n`,
        );
      }
      // The library's widget layout, with a layer underneath for the map widget's outside
      // (WidgetOutside.kt). App resources override the library's file of the same name.
      const layout = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res/layout');
      fs.mkdirSync(layout, { recursive: true });
      fs.writeFileSync(path.join(layout, 'rn_widget.xml'), widgetLayout(false));
      // The library has a dark-mode copy (the dark image shown): override it too.
      const night = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res/layout-night');
      fs.mkdirSync(night, { recursive: true });
      fs.writeFileSync(path.join(night, 'rn_widget.xml'), widgetLayout(true));
      // Tap feedback: the library flashes a grey ripple over the whole tap area, a big rectangle
      // on the Map widget. A small ivory glow under the finger instead, whatever the area's shape.
      fs.writeFileSync(path.join(layout, 'rn_widget_clickable.xml'), CLICKABLE);
      const drawable = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res/drawable');
      fs.mkdirSync(drawable, { recursive: true });
      fs.writeFileSync(path.join(drawable, 'glim_touch.xml'), TOUCH);
      return cfg;
    },
  ]);
};

const widgetLayout = (dark) => `<?xml version="1.0" encoding="utf-8"?>
<!-- Written by plugins/with-fast-widgets.js: react-native-android-widget's rn_widget.xml plus glim_fx. -->
<FrameLayout xmlns:android="http://schemas.android.com/apk/res/android"
    android:id="@android:id/background"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <FrameLayout
        android:id="@id/glim_fx"
        android:layout_width="match_parent"
        android:layout_height="match_parent" />

    <ImageView
        android:id="@+id/rn_widget_image_light"
        android:layout_width="match_parent"
        android:layout_height="match_parent"
        android:background="@android:color/transparent"
        android:scaleType="matrix"
        android:visibility="${dark ? 'gone' : 'visible'}" />

    <ImageView
        android:id="@+id/rn_widget_image_dark"
        android:layout_width="match_parent"
        android:layout_height="match_parent"
        android:background="@android:color/transparent"
        android:scaleType="matrix"
        android:visibility="${dark ? 'visible' : 'gone'}" />

    <!-- Transparent background: the tap glow (glim_touch) is drawn on it. -->
    <FrameLayout
        android:id="@+id/rn_widget_clickable_container"
        android:layout_width="match_parent"
        android:layout_height="match_parent"
        android:background="@android:color/transparent" />

    <FrameLayout
        android:id="@+id/rn_widget_collection_container"
        android:layout_width="match_parent"
        android:layout_height="match_parent" />
</FrameLayout>
`;

// The library's rn_widget_clickable.xml, with the tap glow instead of its ripple.
const CLICKABLE = `<?xml version="1.0" encoding="utf-8"?>
<!-- Written by plugins/with-fast-widgets.js: react-native-android-widget's rn_widget_clickable.xml with glim_touch. -->
<FrameLayout xmlns:android="http://schemas.android.com/apk/res/android"
    android:id="@+id/rn_widget_clickable_positioner"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <FrameLayout
        android:id="@+id/rn_widget_clickable_area"
        android:layout_width="match_parent"
        android:layout_height="wrap_content"
        android:background="@drawable/glim_touch"
        android:clickable="true"
        android:focusable="true" />
</FrameLayout>
`;

// No mask and no content: an unbounded ripple, a round glow of a fixed size around the finger,
// drawn on the nearest parent with a background (the clickable container).
const TOUCH = `<?xml version="1.0" encoding="utf-8"?>
<!-- Written by plugins/with-fast-widgets.js. -->
<ripple xmlns:android="http://schemas.android.com/apk/res/android"
    android:color="#40F2E8D8"
    android:radius="30dp" />
`;
